package spa.cli

import java.nio.file.Files
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import org.junit.jupiter.api.Test
import spa.agent.facts.CardFacts
import spa.agent.grader.GradingPool
import spa.agent.otags.OtagFile
import spa.agent.synergy.CaresTerm
import spa.agent.synergy.PairTerm
import spa.agent.tags.TagCard
import spa.agent.tags.TagFile

/**
 * SPA-054 criteria 1 and 3: the committed otags files, generated by `spa fetch-tags` from the
 * 2026-11-05T22:00 Oracle Tags bulk file, pinned by their counts, and the cares tags and cares term
 * they give with the committed `fixtures/otags/cares.json`. Numbers from the Architect's
 * independent script (`tools/cares.js`, 2026-11-05).
 */
class OtagsFixturesTest {
    private val data = DataDir(Fixtures.root)

    private fun frozen(set: String): String = Fixtures.root.resolve("otags/v1/$set.json").toString()

    private fun file(set: String): OtagFile =
        OtagFile.parse(Files.readString(Fixtures.root.resolve("otags/$set.json")))

    /** Cards, cards with tags, tags with parents, distinct tags. */
    private fun counts(set: String): List<Int> =
        file(set).let { listOf(it.cards.size, it.tagged, it.total, it.distinct) }

    @Test
    fun `the four committed otags files match the script's counts`() {
        assertEquals(listOf(336, 336, 4583, 686), counts("trk"))
        assertEquals(listOf(276, 276, 3864, 636), counts("msh"))
        assertEquals(listOf(188, 188, 2648, 521), counts("hob"))
        assertEquals(listOf(280, 280, 3976, 618), counts("fra"))
    }

    @Test
    fun `each committed file is its set's sealed pool in collector order, with the attribution`() {
        for (set in listOf("trk", "msh", "hob", "fra")) {
            val file = file(set)
            val pool = GradingPool.printings(Commands.loadIndex(data, set)).map(GradingPool::id)

            assertEquals(set, file.set)
            assertEquals(pool, file.cards.map { it.id }, set)
            assertEquals("Card tags from Scryfall Tagger (tagger.scryfall.com)", file.attribution)
            assertEquals(file.encode(), Files.readString(Fixtures.root.resolve("otags/$set.json")))
        }
    }

    /** One set's pool with its otags: facts and cares by id, and a no-roles tag card for each. */
    private class Pool(
        val cards: List<TagCard>,
        val facts: Map<String, Set<String>>,
        val cares: Map<String, Map<String, Int>>,
    ) {
        val term: PairTerm =
            assertNotNull(CaresTerm.forTable(TagFile("x", "", emptyList(), cards), facts, cares))

        fun id(name: String): TagCard = cards.single { it.name == name }

        fun cares(a: String, b: String): Int = term.score(id(a), id(b))
    }

    private fun load(set: String): Pool {
        val index = Commands.loadIndex(data, set)
        // Every set is read from its frozen copy, without its Fable file (SPA-058, SPA-059).
        val inputs = assertNotNull(Otags.load(data, set, frozen(set), fable = false))
        val facts = CardFacts.load(data.scryfall, index, otags = inputs.otags)
        val cards =
            GradingPool.printings(index).map {
                TagCard(GradingPool.id(it), it.card.name, emptyList(), emptyList())
            }
        return Pool(cards, facts, inputs.cares)
    }

    private fun withCares(set: Pool): Int =
        set.cards.count { set.cares[it.id].orEmpty().isNotEmpty() }

    @Test
    fun `trk cares counts and pinned pairs match the script`() {
        val trk = load("trk")

        assertEquals(109, withCares(trk))
        val scores =
            trk.cards.indices.flatMap { i ->
                (i until trk.cards.size).map { j ->
                    Triple(trk.cards[i], trk.cards[j], trk.term.score(trk.cards[i], trk.cards[j]))
                }
            }
        val nonzero = scores.filter { it.third != 0 }
        assertEquals(6078, nonzero.size)
        assertEquals(33, nonzero.count { it.first.id == it.second.id })
        assertEquals(8, scores.maxOf { it.third })
        assertEquals(
            listOf("Data, New Life with Jhoira, Weatherlight Captain"),
            scores.filter { it.third == 8 }.map { "${it.first.name} with ${it.second.name}" },
        )

        val sisay = "Sisay, Weatherlight Captain"
        assertEquals(3, trk.cares[trk.id(sisay).id]!!["legendary"])
        assertEquals(3, trk.cares(sisay, "Gowron, Eager for Battle"))
        assertEquals(3, trk.cares("Gowron, Eager for Battle", sisay))
        assertEquals(0, trk.cares(sisay, "Moopsy"))

        val spock = "Mr. Spock, Science Officer"
        assertEquals(3, trk.cares[trk.id(spock).id]!!["otag:draw"])
        assertEquals(6, trk.cares(spock, spock))
    }

    @Test
    fun `msh, hob and fra cards with cares tags match the script`() {
        assertEquals(66, withCares(load("msh")))
        assertEquals(54, withCares(load("hob")))
        assertEquals(67, withCares(load("fra")))
    }
}
